from mk import *

def fig():
    g = Fig(560, 220, "תרשים א: שני גופים A ו-B צמודים זה לזה על משטח אופקי, וכוח F דוחף את A. תרשים ב: גוף B מונח על גוף A, וכוח F דוחף את A")
    g.ground(30, 260, 110)
    g.block(130, 88, 44, 44, "A"); g.block(172, 92, 36, 36, "B"); g.arrow(60, 80, 106, 80, "F", lx=70, ly=70)
    g.heb(150, 140, "תרשים א")
    g.ground(300, 530, 190)
    g.block(400, 168, 50, 44, "A"); g.block(400, 128, 36, 36, "B"); g.arrow(330, 160, 373, 160, "F", lx=340, ly=150)
    g.heb(420, 214, "תרשים ב")
    return g

E(id="bagrut-2009-q2", year=2009, label="2009 שאלה 2", topic="dynamics", sub="dyn-friction", diff=3, fig=fig,
  stem=r"שני גופים, $A$ ו-$B$, צמודים זה לזה, ומונחים על משטח אופקי לא חלק. ברגע מסוים מפעילים על גוף $A$ כוח אופקי קבוע $F$, כמתואר בתרשים א, והגופים מתחילים לנוע ימינה.",
  parts=[
    P("א", r"האם הכוח שגוף $A$ מפעיל על גוף $B$, בזמן תנועת הגופים, גדול מהכוח שגוף $B$ מפעיל על גוף $A$, קטן ממנו או שווה לו? נמק את תשובתך.", choice(["גדול", "קטן", "שווה"], 2), ["principle"], [
        S(r"החוק השלישי של ניוטון", r"כוחות של שני גופים זה על זה תמיד שווים בגודלם והפוכים בכיוונם, גם בתאוצה", r"\vec F_{AB} = -\vec F_{BA}"),
    ], r"שווה", key=r"שווים, לפי החוק השלישי"),
    P("ב", r"נתון: $m_B = 2\,\text{kg}$, $m_A = 3\,\text{kg}$, $F = 13\,\text{N}$. מקדם החיכוך הקינטי בין כל גוף למשטח $\mu_k = 0.1$. חשב את הכוח שגוף $A$ מפעיל על גוף $B$.", num(5.2, "N"), ["fbd", "principle", "algebra"], [
        S(r"תאוצת המערכת", r"החיכוך על שני הגופים יחד: $\mu(m_A + m_B)g = 5\,\text{N}$", r"a = \frac{13 - 5}{5} = 1.6\,\text{m/s}^2"),
        S(r"החוק השני ל-$B$", r"על $B$ פועלים הכוח מ-$A$ קדימה והחיכוך אחורה", r"F_{AB} - \mu m_B g = m_B a"),
        S(r"מציבים", r"מבודדים את F_AB", r"F_{AB} = 2 \cdot 1.6 + 0.1 \cdot 20 = 5.2\,\text{N}"),
    ], r"$5.2\,\text{N}$", key=r"5.2 N"),
    P("ג", r"הכוח $F$ פועל במשך כמה שניות בלבד. אחרי שהכוח $F$ מפסיק לפעול, מהו הכוח שגוף $A$ מפעיל על גוף $B$? פרט את תשובתך (התייחס לגופים כאל גופים קשיחים).", num(0, "N"), ["fbd", "principle", "algebra"], [
        X(r"בודקים מה הייתה התאוצה של כל גוף אילו נע לבד, בלי כוח ביניהם. אחרי שהכוח $F$ מפסיק, הכוח האופקי היחיד על כל גוף הוא כוח החיכוך, נגד כיוון התנועה."),
        S(r"משוואת כוחות לגוף $A$", r"החוק השני של ניוטון בציר התנועה. החיכוך הקינטי $\mu N = \mu m_A g$", r"m_A a_A = -\mu m_A g"),
        S(r"מחלקים את משוואת הכוחות במסה $m_A$", r"המסה מופיעה בשני צדי המשוואה, ולכן היא מצטמצמת: התאוצה לא תלויה במסה", r"a_A = -\mu g = -0.1 \cdot 10 = -1\,\text{m/s}^2"),
        S(r"משוואת כוחות לגוף $B$, ומחלקים ב-$m_B$", r"אותו חישוב בדיוק, והמסה $m_B$ מצטמצמת", r"m_B a_B = -\mu m_B g \Rightarrow a_B = -\mu g = -1\,\text{m/s}^2"),
        S(r"מסקנה", r"לשני הגופים אותה האטה גם בלי לדחוף זה את זה, ולכן אין צורך בכוח ביניהם", r"a_A = a_B \Rightarrow F_{AB} = 0"),
    ], r"$0$: לשני הגופים אותה האטה, $\mu g = 1\,\text{m/s}^2$, ולכן הם לא לוחצים זה על זה"),
    P("ד", r"לפניך שלושה היגדים. קבע מהו ההיגד הנכון, ונמק את תשובתך. (1) ברגע שהכוח $F$ מפסיק לפעול, שני הגופים נעצרים מיד. (2) אחרי שהכוח $F$ מפסיק לפעול, שני הגופים ייעצרו כעבור אותו זמן (גדול מ-$0$). (3) אחרי שהכוח $F$ מפסיק לפעול, גוף $A$ ייעצר מוקדם יותר מגוף $B$.", choice(["(1)", "(2)", "(3)"], 2), ["principle", "fbd", "understanding"], [
        X(r"בזמן הדחיפה גוף $A$ דוחף את גוף $B$, ולכן הגופים לחוצים זה אל זה ופועל ביניהם כוח נורמלי. ברגע שהכוח $F$ מפסיק, הלחץ הזה לא נעלם מיד: בזמן הניתוק עדיין פועל בין הגופים כוח נורמלי."),
        S(r"הכוח הנורמלי על גוף $B$", r"$A$ דוחף את $B$ קדימה, ולכן הנורמלי על $B$ פועל בכיוון התנועה ומקטין את ההאטה שלו", r"\vec N_{A \to B}:\ \rightarrow"),
        S(r"הכוח הנורמלי על גוף $A$", r"לפי החוק השלישי של ניוטון, $B$ דוחף את $A$ בכוח שווה ומנוגד, כלומר נגד כיוון התנועה. הכוח הזה מצטרף לחיכוך ומגדיל את ההאטה של $A$", r"\vec N_{B \to A} = -\vec N_{A \to B}:\ \leftarrow"),
        S(r"מסקנה", r"בזמן הניתוק $A$ מאט יותר מ-$B$, ולכן מהירותו קטנה יותר מזו של $B$, והגופים נפרדים. אחר כך לשניהם אותה האטה ($\mu g$), ולכן $A$, שהתחיל עם מהירות קטנה יותר, נעצר ראשון", r"|a_A| > |a_B| \Rightarrow v_A < v_B \Rightarrow t_A < t_B"),
        X(r"* דוגמה נוספת למי שרוצה: אפשר לדמיין קפיץ קטן ודחוס בין שני הגופים. בזמן הדחיפה הקפיץ נדחס. כשהכוח $F$ מפסיק, הקפיץ משתחרר ודוחף את $B$ קדימה ואת $A$ אחורה, ולכן $A$ נעצר קודם."),
    ], r"היגד (3): בזמן הניתוק הכוח הנורמלי פועל על $B$ בכיוון התנועה ועל $A$ נגד כיוון התנועה, ולכן $A$ נעצר ראשון", key=r"(3)"),
    P("ה", r"במקרה אחר, מדביקים את גוף $B$ על גוף $A$ (תרשים ב). מפעילים על גוף $A$ כוח ששווה לכוח הנתון בסעיף ב. האם תאוצת הגופים $A$ ו-$B$ במצב זה גדולה מתאוצת הגופים במצב שמתואר בסעיף ב, שווה לה או קטנה ממנה? נמק.", choice(["גדולה", "שווה", "קטנה"], 1), ["fbd", "principle"], [
        S(r"החיכוך", r"הנורמלי על המשטח הוא כל המשקל, כמו קודם", r"f = \mu(m_A + m_B)g = 5\,\text{N}"),
        S(r"התאוצה", r"אותו כוח, אותו חיכוך, אותה מסה", r"a = \frac{13 - 5}{5} = 1.6\,\text{m/s}^2"),
    ], r"שווה", key=r"התאוצות שוות"),
  ],
  concepts=["החוק השלישי של ניוטון", "כוח מגע בין גופים", "חיכוך קינטי", "מערכת גופים"],
  summary=r"שני גופים שנדחפים יחד על משטח עם חיכוך: הכוח ביניהם, מה קורה כשהדחיפה נפסקת, ולמה ערימה אחת על השנייה לא משנה את התאוצה.",
  review='הנחה שלי (לפי החלטת הבעלים).\nסעיף ג: לגופים קשיחים הכוח בין הגופים אחרי שהכוח מפסיק הוא 0. בפתרון מוצגת משוואת הכוחות לכל גוף, והחלוקה במסה מצוינת במפורש.\nסעיף ד: ההסבר הראשי הוא הכוח הנורמלי בזמן הניתוק: על B בכיוון התנועה ועל A נגד כיוון התנועה, ולכן A נעצר ראשון. האנלוגיה של הקפיץ (ההסבר מדף התשובות) מופיעה בסוף, בכוכבית, כדוגמה נוספת.\nמה לבדוק: את הניסוח של שני הסעיפים.')
